#your answer: choose your favourite language in LANGUAGES
#Load Universal NER dataset
LANGUAGES = {
    'en_ewt',
    'choose_your_favourite_language' # available: 'ceb_gja', 'zh_gsd', 'zh_gsdsimp', 'zh_pud', 'hr_set', 'da_ddt', 'en_ewt', 'en_pud', 'de_pud', 'pt_bosque', 'pt_pud', 'ru_pud', 'sr_set', 'sk_snk', 'sv_pud', 'sv_talbanken', 'tl_trg', 'tl_ugnayan'
}

datasets_by_lang = {}
for lang_code in LANGUAGES:
    datasets_by_lang[lang_code.split('_')[0]] = datasets_by_lang.get(lang_code.split('_')[0], dict())
    for split in ["test"]: # we will use the test set for simplicity of the code, cosidering that some languages do not have the validation set.
        ds = load_dataset('universalner/universal_ner', lang_code, split=split, trust_remote_code=True)
        datasets_by_lang[lang_code.split('_')[0]][split] = ds

        print(f'  Loaded ({lang_code}): {len(ds)} {split} examples')
